'use strict';
const $=id=>document.getElementById(id),t=OrionI18n.t;
let variant=OrionProgress.variant('sort'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget;
let stage=0,cars=[],selected=null,solved=false,hintDepth=0,state='ready',history=[],saveFailed=false;
function initial(v=variant,s=stage){const base=[[3,1,4,2],[2,4,1,3],[3,1,2,1,4]][s];return base.map(n=>n+v*2);}
function inOrder(a=cars,s=stage){return a.every((n,i)=>i===0||(s===1?a[i-1]>=n:a[i-1]<=n));}
function resetTrial(){cars=initial();selected=null;solved=false;hintDepth=0;state='ready';history=[];saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('sort')){variant=v;stage=0;resetTrial();}
function choose(i){if(solved||!Number.isInteger(i)||i<0||i>=cars.length)return;if(selected===null){selected=i;state='selected';}else if(selected===i){selected=null;state='ready';}else{history.unshift([cars[selected],cars[i]]);[cars[selected],cars[i]]=[cars[i],cars[selected]];selected=null;state='swapped';}render();$('car'+i).focus();}
function check(){if(solved)return;if(!inOrder()){state='wrong';render();return;}solved=true;selected=null;state='success';if(stage===2)saveFailed=!OrionProgress.earn('order');render();if(stage<2)$('next').focus();}
function hints(){const i=cars.findIndex((n,i)=>i>0&&(stage===1?cars[i-1]<n:cars[i-1]>n));return[t('Read the arrow: the order runs from left to right. Compare the number labels, not the crystal colour.','按箭頭由左至右讀，依照數字標籤排列，不是水晶顏色。'),stage===1?t('The largest number belongs at the left. Find it, then swap it into that place.','最大的數字放最左邊。找出它，再交換到那個位置。'):t('The smallest number belongs at the left. Find it, then swap it into that place. Equal numbers can sit together.','最小的數字放最左邊。找出它，再交換到那個位置。相同數字可以並排。'),i<0?t('Every neighbouring pair is in order. Send the train!','每對相鄰數字都排好了。開出列車吧！'):t(`Carriages ${i} and ${i+1} are out of order. Tap each one to swap them, then look again.`,`第 ${i} 和 ${i+1} 節車廂次序不對。各點一下交換，再觀察。`)];}
function render(){const complete=solved&&stage===2,count=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Crystal Express · Orion','水晶列車站 · Orion');$('stageTitle').textContent=t(`Train ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 班列車 · 第 ${variant+1} 組`);$('sceneStatus').textContent=complete?t('The treasury is open. All aboard!','寶庫打開了。上車吧！'):t(`Trains restored · ${count} / 3`,`已修復 ${count} / 3 班列車`);$('seals').textContent=Array.from({length:3},(_,i)=>i<count?'◆':'◇').join(' ');$('progressCount').textContent=$('sceneStatus').textContent;$('progressBar').value=count;$('scene').classList.toggle('complete',complete);$('mission').textContent=t('Tap one carriage, then another to swap them. Put the numbers in the requested order, then send the train.','先點一節車廂，再點另一節交換位置。把數字按指定次序排好，再開出列車。');$('track').innerHTML=cars.map((n,i)=>`<button id="car${i}" class="car" aria-pressed="${selected===i}" ${solved?'disabled':''} aria-label="${t(`Carriage ${i+1}, number ${n}. Select to swap.`,`第 ${i+1} 節車廂，數字 ${n}。選取以交換。`)}"><span class="gem" aria-hidden="true">◆</span><strong>${n}</strong><small>${t(`Place ${i+1}`,`位置 ${i+1}`)}</small></button>`).join('');cars.forEach((_,i)=>$('car'+i).onclick=()=>choose(i));$('selection').textContent=selected===null?t('Choose two carriages to exchange their places.','選兩節車廂，交換它們的位置。'):t(`Carriage ${selected+1} selected. Choose another, or tap it again to cancel.`,`已選第 ${selected+1} 節。選另一節，或再點一下取消。`);$('goal').innerHTML=t('LEFT → RIGHT','左 → 右')+`<strong>${stage===1?t('Largest → smallest','最大 → 最小'):t('Smallest → largest','最小 → 最大')}</strong>`+(stage===2?t('Equal numbers may sit next to each other.','相同數字可以並排。'):'');
 const msg={ready:t('The station signal is waiting for your train.','車站訊號正等着你的列車。'),selected:t('One carriage selected. Tap another to swap.','已選一節車廂。點另一節便會交換。'),swapped:t('Places exchanged. Check the order from left to right.','位置交換了。由左至右檢查次序。'),wrong:t('Some numbers are still out of order. Keep swapping — there is no move limit.','有些數字次序仍未排好。繼續交換吧，次數不限。'),success:t('In order! The train delivers a crystal key.','排好了！列車送來一把水晶鑰匙。')};$('feedback').textContent=msg[state];$('log').innerHTML=history.slice(0,5).map(([a,b])=>`<li>${a} ↔ ${b}</li>`).join('')||`<li>${t('Your swaps will appear here.','交換紀錄會顯示在這裡。')}</li>`;for(const id of ['check','retry'])$(id).hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved||hintDepth===3;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintDepth>0));$('hints').hidden=!hintDepth;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('');$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('order')?t('Order Sigil saved in your collection.','秩序符印已存入收藏。'):'';
}
$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();$('car0').focus();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);render();};$('replay').onclick=()=>{const v=OrionProgress.nextVariant('sort',variant);observedVariant=OrionProgress.variant('sort');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('order');render();};
function syncProgress(){const v=OrionProgress.variant('sort'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('order')&&!saveFailed)resetMission();else render();}
window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
